import {registerChecks, assert, waitFor} from './advanced-checks.js';

const require = (root, selector, message) => { const node = root.querySelector(selector); assert(Boolean(node), message || `missing ${selector}`); return node; };
const action = (actions, name) => assert(actions.some(item => item.action === name), `missing ${name} action`);
const submit = (root, actions, name) => { const form = require(root, `form[data-ely-submit="${name}"]`); assert(form.checkValidity(), `${name} form is invalid`); form.dispatchEvent(new Event('submit', {bubbles:true,cancelable:true})); action(actions, name); return form; };
const clickAction = (root, actions, name) => { const button = require(root, `[data-ely-action="${name}"]`); button.click(); action(actions, name); };

const shell = async ({root,actions}) => {
 const kind=require(root,'[data-native-kind]').dataset.nativeKind,host=detail=>root.dispatchEvent(new CustomEvent('ely:shell-state',{detail}));
 if(kind==='TitleBar'){const title=require(root,'.ely-native-titlebar');assert(title.querySelector('strong').textContent==='Ely — Projects'&&title.dataset.platform==='mac','source title/platform lost');clickAction(root,actions,'search');return;}
 if(kind==='WindowControls'){const controls=require(root,'.ely-native-window-controls'),buttons=controls.querySelectorAll('button');assert(controls.dataset.platform==='mac'&&buttons.length===3,'source Mac control set lost');buttons[0].click();action(actions,'close');return;}
 if(kind==='StatusBar'){const bar=require(root,'.ely-native-statusbar');assert(bar.textContent.includes('Ln 12, Col 4')&&bar.textContent.includes('UTF-8')&&bar.textContent.includes('Synced'),'source status values lost');clickAction(root,actions,'switch-branch');return;}
 if(kind==='ColumnShell'){const columns=root.querySelectorAll('[data-shell-column]');assert(columns.length===2&&columns[0].style.width==='240px'&&columns[1].textContent.includes('What should we build?'),'source columns lost');const choice=require(columns[0],'[data-shell-select="inbox"]');choice.click();assert(choice.getAttribute('aria-current')==='true','column selection did not persist');return;}
 if(kind==='WindowDragRegion'){const region=require(root,'[data-shell-drag]');assert(region.textContent.includes('Double-click to zoom'),'source drag label lost');region.dispatchEvent(new MouseEvent('dblclick',{bubbles:true}));action(actions,'zoom-window');return;}
 if(kind==='WindowResizeBorder'){assert(require(root,'[data-shell-resize]').dataset.shellResize==='false'&&require(root,'[data-native-shell-note]').textContent.includes('Linux'),'source system border contract lost');return;}
 if(kind==='NativeMenu'){assert(require(root,'[data-native-shell-note]').querySelectorAll('p').length===3,'source menu notes lost');return;}
 if(kind==='Toolbar'){const toolbar=require(root,'.ely-native-toolbar');assert(toolbar.querySelectorAll('[role="group"]').length===3&&toolbar.querySelectorAll('[role="separator"]').length===2,'source tool groups lost');clickAction(root,actions,'undo');clickAction(root,actions,'share');return;}
 if(kind==='ActivityBar'){const nav=require(root,'.ely-native-activity');assert(nav.querySelectorAll('[data-shell-select]').length===7&&require(nav,'small').textContent==='3','source rail items/badge lost');require(nav,'[data-shell-select="git"]').click();assert(require(root,'[data-shell-selected]').textContent==='git','activity selection did not update');return;}
 if(kind==='TabBar'){const bar=require(root,'[data-shell-tabs]');assert(bar.querySelectorAll('[role="tab"]').length===3&&bar.dataset.selected==='roadmap','source tabs lost');require(bar,'[data-shell-tab="roadmap"] [data-shell-tab-close]').click();assert(bar.dataset.selected==='inbox'&&bar.querySelectorAll('[role="tab"]').length===2,'closing active tab did not select first remaining');require(bar,'[data-shell-tab-add]').click();assert(bar.dataset.selected==='draft-1'&&bar.querySelectorAll('[role="tab"]').length===3,'local add did not append source draft');action(actions,'close-tab');action(actions,'add-tab');return;}
 if(kind==='SplashScreen'){assert(require(root,'progress').value===62&&require(root,'[data-shell-status]').textContent==='Loading workspace…','source splash state lost');host({progress:0,status:'Host starting'});assert(require(root,'progress').value===0&&require(root,'[data-shell-status]').textContent==='Host starting','zero host progress lost');return;}
 if(kind==='AboutDialog'){assert(root.textContent.includes('0.1.0 (2026.09)')&&root.querySelectorAll('.ely-native-about a').length===2,'source about metadata lost');require(root,'[data-shell-copy]').click();assert(actions.at(-1).text==='0.1.0 (2026.09)','copy request lost caller version');return;}
 if(kind==='TrayIcon'){const tray=require(root,'[data-shell-tray]');require(root,'[data-shell-tray-toggle]').click();assert(tray.dataset.shown==='false'&&actions.at(-1).shown===true,'tray request fabricated OS confirmation');host({shown:true,lastPick:'Open gallery'});assert(tray.dataset.shown==='true'&&!require(root,'[data-shell-tray-pick]').disabled&&require(root,'[data-shell-last-pick]').textContent==='Open gallery','host tray confirmation lost');return;}
 if(kind==='DockBadge'){require(root,'[data-shell-badge="3"]').click();assert(actions.at(-1).badge==='3'&&require(root,'[data-shell-dock]').dataset.value==='','badge request fabricated confirmation');host({badge:'3'});assert(require(root,'[data-shell-dock-status]').textContent==='The Dock shows “3”.','host badge lost');return;}
 if(kind==='SystemNotification'){assert(require(root,'[data-native-shell-note]').textContent.includes('posts no system notification'),'source unsupported notification note lost');return;}
 if(kind==='MultiWindow Manager'){assert(require(root,'[data-shell-empty]'),'empty host window state lost');require(root,'[data-shell-new-window]').click();action(actions,'new-window');assert(!root.querySelector('[data-shell-window]'),'new window request fabricated a window');host({windows:[{Value:'host-window',Label:'Caller window'}]});require(root,'[data-shell-window]').click();assert(actions.at(-1).value==='host-window','host window identity lost');return;}
 if(kind==='WindowSwitcher'){const opener=require(root,'[data-shell-switch-open]'),dialog=require(root,'[data-shell-switcher]');host({windows:[{Value:'one',Label:'First'},{Value:'two',Label:'Second'}]});opener.click();assert(dialog.open,'switcher did not open');dialog.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowDown',bubbles:true}));const closed=dialogClose(dialog);dialog.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true}));await closed;assert(actions.at(-1).value==='two'&&document.activeElement===opener,'switcher lost keyboard selection or focus return');return;}
 if(kind==='QuickLauncher'){assert(require(root,'[data-native-shell-note]').textContent.includes('navigation::QuickLauncher'),'source navigation delegation note lost');return;}
 if(kind==='MiniWindow'){const button=require(root,'[data-shell-mini-open="mini"]');button.click();assert(actions.at(-1).width===320&&actions.at(-1).height===96&&actions.at(-1).corner==='bottom-right','mini host request lost source bounds');return;}
 if(kind==='UpdateBanner'){const rows=root.querySelectorAll('[data-shell-update]');assert(rows.length===3&&rows[1].querySelector('progress').value===42&&rows[2].textContent.includes('Restart to update'),'source update states lost');clickAction(root,actions,'download-update');assert(rows[0].dataset.state==='available','download request fabricated progress');return;}
 if(kind==='UpdateDialog'){assert(root.querySelectorAll('.ely-native-update-dialog li').length===4&&root.textContent.includes('You have 0.1.0.'),'source update notes/version lost');clickAction(root,actions,'download-update');return;}
 if(kind==='CrashReporter'){const disclosure=require(root,'.ely-native-crash details');assert(disclosure.open&&disclosure.querySelector('pre').textContent.includes('EXC_BAD_ACCESS'),'source crash report lost');require(root,'[data-shell-send-report]').click();assert(actions.at(-1).text.includes('layout::dock::restore'),'host report content lost');return;}
 if(kind==='OfflineIndicator'){const pill=require(root,'.ely-native-connectivity');assert(pill.hidden,'online indicator should start hidden');require(root,'[data-shell-connect="offline"]').click();assert(!pill.hidden&&pill.textContent.includes('Offline'),'offline state lost');require(root,'[data-shell-connect="online"]').click();assert(!pill.hidden&&pill.textContent.includes('Back online'),'online transition notice lost');await waitFor(()=>pill.hidden,3000);return;}
 if(kind==='ZoomControl'){const zoom=require(root,'[data-shell-zoom]');require(zoom,'[data-native-zoom="1"]').click();assert(require(zoom,'[data-native-zoom-value]').textContent==='110%','source zoom step failed');host({percent:67});require(zoom,'[data-native-zoom="-1"]').click();assert(require(zoom,'[data-native-zoom-value]').textContent==='50%'&&require(zoom,'[data-native-zoom="-1"]').disabled,'nonlinear zoom/min boundary lost');require(zoom,'[data-native-zoom="0"]').click();assert(require(zoom,'[data-native-zoom-value]').textContent==='100%','number reset failed');return;}
 throw Error('Missing shell check '+kind);
};
const titleBar=shell,windowControls=shell,statusBar=shell;
const generation = ({root,actions}) => { if(root.dataset.elyKind==='GenerationQueue'){const rows=root.querySelectorAll('.ely-native-generation-queue li');assert(rows.length===5,'generation queue lost source five job states');assert(rows[0].querySelector('img')&&rows[1].querySelector('progress').value===62&&rows[2].dataset.nativeOutcome==='queued'&&rows[3].dataset.nativeOutcome==='queued'&&rows[4].textContent.includes('out of memory on the GPU'),'generation queue lost source outcomes');clickAction(root,actions,'retry-generation');return;}const cards=root.querySelectorAll('.ely-native-generation-results article');assert(cards.length===4,'generation grid lost source four outcomes');assert(cards[0].querySelector('img')&&cards[1].querySelector('img')&&cards[2].textContent.includes('40%')&&cards[3].textContent.includes('Stopped by the content filter'),'generation grid lost source result states');clickAction(root,actions,'open-generation');clickAction(root,actions,'retry-generation'); };
const variation = ({root,actions}) => {const ab=root.querySelector('[data-native-ab]');if(ab){const sides=ab.querySelectorAll('[data-native-ab-side]');assert(sides.length===2&&sides[0].querySelector('strong').textContent==='Model A','blind model names leaked');ab.querySelector('[data-native-verdict="1"]').click();assert(sides[1].dataset.preferred==='true'&&sides[1].querySelector('strong').textContent==='Juniper 2'&&ab.querySelector('nav').hidden,'verdict did not reveal the winning model');return;}const picker=require(root,'.ely-native-variation-picker'),options=picker.querySelectorAll('input[type="radio"]');assert(options.length===4&&picker.querySelector('figure img'),'variation picker lost source hero and four choices');options[1].checked=true;options[1].dispatchEvent(new Event('change',{bubbles:true}));assert(options[1].closest('label').hasAttribute('data-native-selected')&&picker.querySelector('figure img').src===options[1].closest('label').querySelector('img').src,'variation did not update hero and selection');clickAction(root,actions,'upscale'); };
const mask = ({root}) => {const canvas=require(root,'canvas[data-native-mask]'),before=JSON.parse(canvas.dataset.geometry),bounds=canvas.getBoundingClientRect();assert(before.length===1&&before[0].radius===.07&&before[0].points.length===5,'initial source tree mask lost');canvas.dispatchEvent(new KeyboardEvent('keydown',{bubbles:true,key:']'}));assert(Number(require(root,'[data-native-brush]').value)>.05,'bracket did not enlarge brush');canvas.dispatchEvent(new KeyboardEvent('keydown',{bubbles:true,key:'x'}));assert(canvas.dataset.mode==='erase','X did not select erasing');for(const type of ['pointerdown','pointermove','pointerup'])canvas.dispatchEvent(new PointerEvent(type,{bubbles:true,clientX:bounds.left+bounds.width*.12,clientY:bounds.top+bounds.height*.3,pointerId:1,button:0}));const strokes=JSON.parse(canvas.dataset.geometry);assert(strokes.length===2&&strokes[1].erase&&strokes[1].points.every(p=>p.every(v=>v>=0&&v<=1)),'mask lost normalized erasing geometry');require(root,'[data-native-mask-undo]').click();assert(JSON.parse(canvas.dataset.geometry).length===1,'undo lost source stroke');require(root,'[data-native-mask-clear]').click();assert(JSON.parse(canvas.dataset.geometry).length===0,'clear failed'); };
const generationPanel = ({root,actions}) => {
 const panel=require(root,'[data-native-generation-panel]'),prompt=require(panel,'[data-native-prompt]'),styles=panel.querySelectorAll('[data-native-style]'),ratios=panel.querySelectorAll('[data-native-ratio]');
 assert(styles.length===6&&ratios.length===5,'panel lost source styles or aspect ratios');styles[2].click();ratios[0].click();
 assert(panel.elements.namedItem('style').value==='mono'&&panel.elements.namedItem('aspectRatio').value==='1:1','panel choices lost form values');
 const original=prompt.value;clickAction(root,actions,'enhance-prompt');assert(prompt.value===original,'enhancer fabricated a result');
 root.dispatchEvent(new CustomEvent('ely:prompt-suggestion',{detail:{suggestion:original+', morning light'}}));assert(!require(panel,'[data-native-suggestion]').hidden,'host suggestion not shown');
 require(panel,'[data-native-resolve="keep"]').click();assert(prompt.value===original,'keep mine changed caller prompt');
 root.dispatchEvent(new CustomEvent('ely:prompt-suggestion',{detail:{suggestion:original+', morning light'}}));require(panel,'[data-native-resolve="use"]').click();assert(prompt.value.endsWith(', morning light'),'suggestion not accepted');
 const seed=require(panel,'[data-native-seed]');seed.value='4294967295';seed.dispatchEvent(new Event('input',{bubbles:true}));seed.value='4294967296';seed.dispatchEvent(new Event('input',{bubbles:true}));assert(seed.value==='4294967295','seed overflow changed valid caller value');
 const tag=require(panel,'[data-native-tag-entry]');tag.value='fog';tag.dispatchEvent(new KeyboardEvent('keydown',{bubbles:true,key:'Enter'}));assert(panel.elements.namedItem('negativePrompt').value==='blurry,watermark,people,fog','tag entry lost source exclusions');submit(root,actions,'generate');
};
const generatedAudio = ({root,actions}) => {
 const player=require(root,'[data-native-generated-audio]'),wave=require(player,'[data-native-generated-wave]');
 assert(wave.querySelectorAll('rect').length===56&&!player.querySelector('audio'),'source generated audio fixture must expose peaks without fabricated audio');
 assert(player.dataset.position==='12','caller position lost');require(player,'[data-native-generated-play]').click();action(actions,'play');assert(player.dataset.position==='12'&&player.dataset.playing==='true','play request fabricated progress');
 wave.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowRight',bubbles:true}));assert(Number(player.dataset.position)===13.6,'seek did not retain source duration');
 root.dispatchEvent(new CustomEvent('ely:generated-audio',{detail:{position:0,playing:false,making:0}}));assert(!require(player,'[data-native-audio-making]').hidden&&require(player,'header button').disabled,'zero making progress treated as ready');
 root.dispatchEvent(new CustomEvent('ely:generated-audio',{detail:{making:null}}));assert(require(player,'[data-native-audio-making]').hidden&&!require(player,'header button').disabled,'host completion failed');
 clickAction(root,actions,'regenerate-audio');clickAction(root,actions,'download-audio');
};
const media = async ({root,actions}) => {
 const player=require(root,'[data-native-video-player],[data-native-audio-player]'),video=player.hasAttribute('data-native-video-player'),play=require(player,'[data-native-play],[data-native-transport-action="play"]');
 assert(!player.querySelector('[data-native-media]'),'source frame fixture unexpectedly substitutes sample playback');
 assert(Number(player.dataset.nativePosition)===(video?34:64),'source initial playhead lost');
 play.click();assert(player.dataset.playing==='true'&&play.getAttribute('aria-label')==='Pause','host play request not reflected');
 const seek=require(player,'[data-native-seek]');seek.value='500';seek.dispatchEvent(new Event('input',{bubbles:true}));assert(Number(player.dataset.nativePosition)===(video?45:111),'local seek did not preserve duration');
 root.dispatchEvent(new CustomEvent('ely:media-state',{detail:{position:video?34:64,playing:false}}));assert(player.dataset.playing==='false'&&play.getAttribute('aria-label')==='Play','host update not reflected');
 if(video){assert(!require(player,'[data-native-caption]').hidden&&require(player,'[data-native-caption]').textContent==='Light falls on the stair.','source caption missing');player.dispatchEvent(new KeyboardEvent('keydown',{bubbles:true,key:'j'}));assert(Number(player.dataset.nativePosition)===24,'J did not seek ten seconds');player.dispatchEvent(new KeyboardEvent('keydown',{bubbles:true,key:'l'}));assert(Number(player.dataset.nativePosition)===34,'L did not seek ten seconds');player.dispatchEvent(new KeyboardEvent('keydown',{bubbles:true,key:'c'}));assert(require(player,'[data-native-caption]').hidden,'C did not toggle captions');require(player,'[data-native-video-speed]').click();assert(player.dataset.speed==='1.25','six-speed cycle lost');play.click();await waitFor(()=>player.dataset.nativeControlsVisible==='false',3000);require(player,'[data-native-caption-toggle]').focus();assert(player.dataset.nativeControlsVisible==='true','focused controls stayed hidden');root.dispatchEvent(new CustomEvent('ely:media-state',{detail:{playing:false}}));}
 else{assert(require(player,'header strong').textContent==='Tall Windows'&&require(player,'header small').textContent==='Aster Quartet','source track metadata lost');assert(require(player,'[data-native-remaining-time]').textContent==='−02:38','remaining time lost');clickAction(root,actions,'previous-track');clickAction(root,actions,'next-track');}
};
const standaloneAudio = ({root,actions}) => { const name=root.dataset.elyComponent;if(name==='media/AudioWaveform'){const wave=require(root,'[data-native-waveform]'),bars=wave.querySelectorAll('[data-native-wave-bar]'),before=Number(wave.dataset.nativePosition);assert(bars.length===Math.max(1,Math.floor(((wave.clientWidth||640)+2)/5))&&JSON.parse(wave.dataset.peaks).length===180&&[...bars].some(bar=>bar.classList.contains('is-played')),'waveform lost source peaks, responsive bar pitch, or progress');wave.dispatchEvent(new KeyboardEvent('keydown',{bubbles:true,key:'ArrowRight'}));assert(Number(wave.dataset.nativePosition)===before+5,'waveform arrow did not seek five seconds');return}if(name==='media/AudioSpectrum'||name==='media/Visualizer'){const spectrum=require(root,'[data-native-spectrum]');assert(spectrum.querySelectorAll('[data-native-spectrum-bar]').length===40,'spectrum lost 40 source frequency bars');root.dispatchEvent(new CustomEvent('ely:samples',{bubbles:true,detail:{samples:[{height:15},{height:60},{height:30}]}}));assert(spectrum.querySelectorAll('[data-native-spectrum-bar]').length===3,'spectrum did not accept host levels');return}if(name==='media/VolumeControl'){const control=require(root,'[data-native-volume-control]'),mute=require(control,'[data-native-volume-mute]'),range=require(control,'[data-native-volume]');mute.click();assert(control.dataset.nativeMuted==='true'&&range.value==='0'&&mute.getAttribute('aria-label')==='Unmute','volume mute did not set local silent state');range.value='.5';range.dispatchEvent(new Event('change',{bubbles:true}));assert(control.dataset.nativeMuted==='false'&&mute.getAttribute('aria-label')==='Mute','volume slider did not unmute');action(actions,'toggle-mute');return}if(name==='media/PlaybackSpeedControl'){const menu=require(root,'[data-native-speed-menu]');menu.open=true;const choice=require(menu,'[data-native-speed-choice="1.5"]');choice.click();assert(require(menu,'[data-native-speed-value]').textContent==='1.5×'&&!menu.open,'speed menu did not select and close');action(actions,'change-playback-speed');return}const transport=require(root,'[data-native-transport]'),buttons=transport.querySelectorAll('button');assert(buttons.length===5,'transport lost shuffle, skip, play, and repeat controls');require(transport,'[data-native-transport-action="shuffle"]').click();assert(require(transport,'[data-native-transport-action="shuffle"]').getAttribute('aria-pressed')==='true','shuffle state did not persist');require(transport,'[data-native-transport-action="play"]').click();assert(require(transport,'[data-native-transport-action="play"]').getAttribute('aria-label')==='Pause','transport play state did not persist');require(transport,'[data-native-transport-action="repeat"]').click();assert(require(transport,'[data-native-transport-action="repeat"]').dataset.nativeRepeat==='one','repeat did not cycle all to one');require(transport,'[aria-label="Previous track"]').click();require(transport,'[aria-label="Next track"]').click();['toggle-shuffle','previous-track','toggle-play','next-track','cycle-repeat'].forEach(name=>action(actions,name));};
const samples = ({root}) => { const waveform=require(root,'[data-native-waveform]'),data=[{x:1,y:2,width:3,height:4},{x:8,y:3,width:3,height:5}];root.dispatchEvent(new CustomEvent('ely:samples',{bubbles:true,detail:{samples:data}}));assert(waveform.dataset.sampleCount==='2','provider samples did not update waveform');assert(waveform.querySelectorAll('[data-native-wave-bar]').length===2,'waveform bars did not update'); };
const frames = ({root,actions}) => {const host=require(root,'[data-native-shots]'),shots=[...host.querySelectorAll('[data-native-shot]')];assert(shots.length===4&&shots.map(s=>s.dataset.duration).join(',')==='5,4,6,4','source shots lost proportional durations');assert(shots[0].style.width==='120px'&&shots[2].style.width==='144px','shot geometry lost 24px per second');assert(!host.querySelector('video'),'source timeline fabricated a video');assert(require(host,'[data-native-shot-playhead]').style.left==='76.8px','source playhead time lost');shots[3].click();assert(shots[3].getAttribute('aria-pressed')==='true'&&require(host,'[data-native-shot-caption]').textContent.includes('failed, timed out'),'shot selection did not show failure reason');clickAction(root,actions,'extend-video');};
const comparison = ({root}) => { const before=require(root,'.ely-native-compare img:not([data-native-compare-after])'),after=require(root,'[data-native-compare-after]'),range=require(root,'[data-native-compare]');assert(before.getAttribute('src')!==after.getAttribute('src'),'comparison lost caller before/after sources');range.value='25';range.dispatchEvent(new Event('input',{bubbles:true}));assert(after.style.clipPath.includes('25%'),'comparison range did not alter overlay'); };
const form = name => ({root,actions}) => { const field=require(root,'form textarea,form input,form select');if(field.tagName==='SELECT')field.selectedIndex=0;else if(field.type!=='file')field.value=field.value||'caller';submit(root,actions,name);assert(actions.find(item=>item.action===name).values.length>0,`${name} action has no form data`); };
const model = ({root,actions}) => {const name=root.dataset.elyKind;if(name==='ModelDownloadManager'){const rows=root.querySelectorAll('[data-native-download]');assert(rows.length===5&&rows[0].querySelector('progress').value===43&&rows[1].querySelector('progress').value===12,'source five download states lost');clickAction(root,actions,'pause-download');assert(actions.at(-1).value==='orchid','download action lost stable key');root.dispatchEvent(new CustomEvent('ely:download',{detail:{key:'orchid',status:'paused',progress:43,content:'Paused by host'}}));assert(!rows[0].querySelector('[data-native-download-action="resume"]').hidden&&rows[0].querySelector('[data-native-download-action="pause"]').hidden,'host pause failed');return;}if(name==='ModelStatus'){if(root.querySelector('[data-native-hardware]')){const rows=root.querySelectorAll('[data-native-reading]');assert(rows.length===3&&rows[1].querySelector('meter').value===93&&rows[0].querySelector('polyline'),'hardware history/threshold data lost');}else{const rows=root.querySelectorAll('[data-native-model-status]');assert(rows.length===3&&rows[0].querySelector('meter').value===7800000000&&rows[0].querySelector('meter').max===24000000000&&rows[1].querySelector('progress').value===62,'model loading and memory bytes lost');}return;}if(name==='FineTuneJobCard'){const card=require(root,'[data-native-tune]');assert(card.querySelectorAll('[data-native-loss] polyline').length===2,'paired source loss curves lost');assert(Math.abs(require(card,'progress').value-54.6666666667)<.00001,'whole-epoch progress lost');const toggle=require(card,'[data-native-loss-toggle="held"]');toggle.click();assert(require(card,'[data-series="held"]').style.display==='none','loss legend did not hide series');clickAction(root,actions,'cancel-tune');return;}const card=require(root,'[data-native-model-card]');assert(card.querySelectorAll('dt').length===3&&card.dataset.inUse==='true','source model facts/in-use state lost');root.dispatchEvent(new CustomEvent('ely:model-use',{detail:{inUse:false}}));clickAction(root,actions,'use-model');assert(actions.at(-1).value==='orchid','use action lost caller key');root.dispatchEvent(new CustomEvent('ely:model-use',{detail:{inUse:true}}));assert(require(card,'[data-native-model-use]').hidden,'host in-use update failed');};
const records = ({root}) => { const filter=require(root,'[data-native-filter]');filter.value='not-present';filter.dispatchEvent(new Event('input',{bubbles:true}));const rows=root.querySelectorAll('[data-native-item]');assert(rows.length===2&&[...rows].every(item=>item.hidden),'record filter did not affect caller rows'); };
const playlist = ({root,actions}) => {const list=require(root,'.ely-native-playlist'),buttons=list.querySelectorAll('[data-native-select]');assert(buttons.length===5&&buttons[4].textContent.includes('Low Sun'),'source playlist lost tracks');buttons[1].dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true}));assert(buttons[1].getAttribute('aria-current')==='true'&&buttons[0].getAttribute('aria-current')==='false'&&list.dataset.playing==='true','Enter did not start selected track');assert(actions.at(-1).key==='stone-stair','track host request lost caller key');};
