const palette = ({root,twin}) => {
 const swatches=[...root.querySelectorAll('[data-native-swatch]')],toggle=require(root,'[data-native-color-safe]'),originalMode=root.dataset.theme,originalChecked=toggle.checked;
 const twinColors=twin?[...twin.querySelectorAll('[data-native-swatch]')].map(node=>node.dataset.nativeSwatch):null;
 assert(swatches.length===8,'palette lost source swatches');const mode=themeMode(root);
 checkPaintedColors(swatches,(originalChecked?sourceSafeCharts:sourceCharts)[mode],'Initial chart colors differ from active source mode');
 try{
  toggle.checked=true;toggle.dispatchEvent(new Event('change',{bubbles:true}));assert(root.dataset.nativeColorSafe==='true','palette state missing');checkPaintedColors(swatches,sourceSafeCharts[mode],'wrong source safe palette for current mode');
  const opposite=mode==='dark'?'light':'dark';root.dataset.theme=opposite;root.dispatchEvent(new Event('ely:theme'));checkPaintedColors(swatches,sourceSafeCharts[opposite],'Local theme mode did not update safe chart colors');
  toggle.checked=false;toggle.dispatchEvent(new Event('change',{bubbles:true}));checkPaintedColors(swatches,sourceCharts[opposite],'Safe toggle did not restore local mode chart colors');
  assert(swatches.every(node=>node.getBoundingClientRect().width===40),'palette dimensions differ');
  if(twin)assert([...twin.querySelectorAll('[data-native-swatch]')].every((node,index)=>node.dataset.nativeSwatch===twinColors[index]),'Local palette changes affected sibling instance');
 }finally{if(originalMode===undefined)delete root.dataset.theme;else root.dataset.theme=originalMode;toggle.checked=originalChecked;root.dispatchEvent(new Event('ely:theme'));toggle.dispatchEvent(new Event('change',{bubbles:true}));}
 checkPaintedColors(swatches,(originalChecked?sourceSafeCharts:sourceCharts)[mode],'Original chart mode/colors were not restored');
};
