const captcha = ({root,actions}) => { const field=require(root,'form input[name]');field.value='caller-response';submit(root,actions,'apply');assert(actions.find(item=>item.action==='apply').values.some(([name,value])=>name===field.name&&value==='caller-response'),'captcha action lost caller response'); };
const documentView = ({root,actions}) => { const pre=require(root,'.ely-native-document pre');assert(pre.textContent.trim(),'document did not render caller value');const button=require(root,'.ely-native-document [data-ely-action]');button.click();assert(actions.length>0,'document host action did not emit'); };

const voicePicker = ({root,actions}) => {const rows=root.querySelectorAll('[data-native-voice]'),host=require(root,'[data-native-voices]');assert(rows.length===4&&rows[3].textContent.includes('Inés'),'source four voices lost');rows[1].querySelector('[data-native-voice-select]').click();assert(host.dataset.selected==='theo'&&!rows[1].querySelector('[data-native-voice-check]').hidden,'voice selection/check failed');rows[0].querySelector('[data-native-voice-play]').click();assert(host.dataset.selected==='theo'&&host.dataset.playing==='iris','sample action changed selected voice');action(actions,'play-voice-sample');rows[0].querySelector('[data-native-voice-play]').click();assert(host.dataset.playing===''&&actions.at(-1).voice===null,'sample stop request lost');};
const dataset = ({root}) => {const host=require(root,'[data-native-dataset]'),rows=()=>[...host.querySelectorAll('[data-native-sample]')].filter(row=>!row.hidden);assert(host.querySelectorAll('[data-native-sample]').length===12&&rows().length===5,'source 12 samples / five-row page lost');require(host,'[data-native-page="2"]').click();assert(rows().length===2&&require(host,'[data-native-page-count]').textContent==='11–12 of 12','last page is not bounded');require(host,'[data-native-sort="tokens"]').click();assert(rows()[0].dataset.tokens==='10','numeric ascending sort failed');rows()[0].querySelector('button').click();assert(!rows()[0].nextElementSibling.hidden&&rows()[0].nextElementSibling.textContent.includes('Ottawa.'),'sample details lost full answer');require(host,'[data-native-sort="tokens"]').click();assert(rows()[0].dataset.tokens==='41','numeric descending sort failed');require(host,'[data-native-sort="tokens"]').click();assert(rows()[0].dataset.nativeSample==='sample-0','third sort did not restore caller order');};
const embedding = ({root}) => {const host=require(root,'[data-native-embedding]'),svg=require(host,'svg');assert(svg.querySelectorAll('circle').length===64,'source 64 embedding points lost');require(host,'[data-native-embedding-group="0"]').click();assert(svg.querySelectorAll('circle').length===48,'legend did not hide one source topic');require(host,'[data-native-embedding-group="0"]').click();assert(svg.querySelectorAll('circle').length===64,'legend did not restore caller points');if(host.dataset.three==='true'){const before=host.dataset.turn;svg.dispatchEvent(new KeyboardEvent('keydown',{bubbles:true,key:'ArrowRight'}));assert(host.dataset.turn!==before,'3D keyboard orbit failed');}};
const promptWorkbench = ({root,actions}) => {const host=require(root,'[data-native-prompt-workbench]'),fields=host.querySelectorAll('[data-native-variable]'),run=require(host,'[data-native-run]');assert(fields.length===2&&run.disabled&&host.querySelectorAll('mark').length===2,'blank variables did not block run');for (const [index,field] of fields.entries()) { field.value=index?'calm':'gardens'; field.dispatchEvent(new Event('input',{bubbles:true})); }assert(!run.disabled,'filled prompt stayed blocked');run.click();const sent=actions.find(item=>item.action==='run-prompt');assert(sent?.prompt==='Write three short notes on gardens in a calm voice.','run lost caller substitutions');assert(host.dataset.running==='true','run did not enter pending state');root.dispatchEvent(new CustomEvent('ely:prompt-output',{detail:{output:'Host answer <plain>',tokens:18,milliseconds:1240}}));assert(require(host,'[data-native-prompt-answer]').textContent==='Host answer <plain>'&&require(host,'[data-native-prompt-stats]').textContent.includes('18 tokens'),'host output/stats lost');};
const promptHistory = ({root,actions}) => {const host=require(root,'[data-native-prompt-history]'),versions=host.querySelectorAll('[data-native-version]');assert(versions.length===4&&host.dataset.chosen==='1','source chosen version lost');assert(require(host,'[data-native-version-diff]').querySelector('del')&&require(host,'[data-native-version-diff]').querySelector('ins'),'word-level added/deleted diff lost');require(host,'[data-native-version-restore]').click();assert(actions.at(-1).key==='v3'&&actions.at(-1).version===1,'restore lost caller version identity');versions[0].click();assert(require(host,'[data-native-version-restore]').hidden,'newest version still offers restore');versions[3].click();assert(require(host,'[data-native-version-heading]').textContent==='The first version','oldest version has wrong comparison base');};

const misc = async ({root,actions}) => {
 const kind=require(root,'[data-native-kind]').dataset.nativeKind,send=form=>form.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true})),host=detail=>root.dispatchEvent(new CustomEvent('ely:misc-state',{detail}));
 if(root.querySelector('[data-misc-source-note]')){assert(require(root,'[data-misc-source-note]').textContent.trim(),'source-only notice missing');if(kind==='IframeEmbed'){assert(root.querySelector('header').textContent.includes('https://example.com'),'embed URL missing');require(root,'header button').click();action(actions,'open')}return;}
 if(kind==='Clock'){assert(/^\d{2}:\d{2}:\d{2}$/.test(require(root,'[data-native-clock]').textContent),'live clock invalid');const face=require(root,'[data-hand="hour"]');assert(face.style.transform.includes('rotate'),'analog hands did not follow clock');if(root.dataset.elyComponent.endsWith('/WorldClock'))assert(root.querySelectorAll('[data-clock-zone]').length===5,'source world zones lost');return;}
 if(kind==='Stopwatch'){const start=require(root,'[data-native-timer]'),side=require(root,'[data-native-reset]');assert(side.disabled&&side.textContent==='Lap','initial lap must be disabled');start.click();await waitFor(()=>require(root,'[data-native-stopwatch]').textContent!=='00:00.0');side.click();assert(root.querySelectorAll('[data-misc-laps] li').length===1,'running lap not recorded');start.click();assert(side.textContent==='Reset'&&start.textContent==='Start','pause state lost');side.click();assert(require(root,'[data-native-stopwatch]').textContent==='00:00.0'&&!root.querySelector('[data-misc-laps] li'),'reset did not clear elapsed and laps');return;}
 if(kind==='Calculator'){const key=k=>{ require(root,`[data-native-calculator-key="${k}"]`).click(); };assert(root.querySelectorAll('[data-native-calculator-key]').length===19,'source 19-key pad lost');key('AC');for (const value of ['2','+','3','×','4','=']) { key(value); }assert(require(root,'[data-native-result]').textContent==='14','calculator precedence failed');key('±');assert(require(root,'[data-native-result]').textContent==='-14','answer sign failed');return;}
 if(kind==='UnitConverter'){const input=require(root,'input[name=value]'),output=require(root,'[data-native-result]');assert(input.value==='1'&&output.textContent==='3.28084 ft','source meter/foot conversion lost');input.value='1.23456789123';input.dispatchEvent(new Event('input',{bubbles:true}));assert(input.value==='1.23456789123'&&Math.abs(Number(output.dataset.value)-1.23456789123/.3048)<1e-10,'converter rounded caller amount');const category=require(root,'[name=category]');assert(category.options.length===7,'source categories lost');category.value='Temperature';category.dispatchEvent(new Event('change',{bubbles:true}));input.value='0';input.dispatchEvent(new Event('input',{bubbles:true}));assert(Math.abs(Number(output.dataset.value)-32)<1e-10,'temperature offset failed');return;}
 if(kind==='QRCodeScanner'){assert(require(root,'.ely-misc-scan-frame svg')&&require(root,'[data-misc-scan-result]').textContent==='https://example.com/ely','source scanner frame/result lost');root.dispatchEvent(new CustomEvent('ely:scan',{detail:{value:'caller:next'}}));assert(require(root,'[data-misc-scan-result]').textContent==='caller:next','scanner ignored host result');return;}
 if(kind==='Captcha'){const form=require(root,'[data-misc-captcha]'),input=require(form,'input');assert(require(form,'img').getAttribute('src').endsWith('w7xk.png'),'source captcha image lost');input.value=' caller code ';send(form);const requested=actions.at(-1);assert(requested.action==='verify'&&requested.value==='caller code'&&form.dataset.state==='checking','captcha lost caller answer or host boundary');host({state:'wrong'});assert(form.dataset.state==='wrong'&&require(form,'[data-misc-error]').textContent,'wrong answer not shown');host({state:'passed'});assert(input.disabled&&form.dataset.state==='passed','host verification not applied');require(form,'[data-misc-refresh]').click();action(actions,'refresh');return;}
 if(kind==='Poll'){const survey=root.querySelector('[data-misc-survey]');if(survey){const before=actions.length;send(survey);assert(actions.length===before&&require(survey,'[data-misc-error]').textContent,'incomplete survey emitted');survey.querySelectorAll('fieldset').forEach(field=>{const control=field.querySelector('input,textarea');if(control.tagName==='TEXTAREA')control.value='Caller next';else control.checked=true});send(survey);assert(actions.at(-1).answers.length===3&&survey.textContent.includes('Thanks.'),'survey lost answers');return}const form=require(root,'[data-misc-poll]'),inputs=form.querySelectorAll('input');assert(inputs.length===3&&form.querySelector('button').disabled,'source poll must begin unanswered');inputs[1].checked=true;inputs[1].dispatchEvent(new Event('change',{bubbles:true}));send(form);assert(actions.at(-1).value==='1'&&form.dataset.voted==='1','vote selection lost');assert(require(form,'[data-vote-option="1"]').dataset.count==='10','gallery host tally not updated');send(form);assert(actions.at(-1).value===null&&form.dataset.voted==='','change vote did not retract');return;}
 if(kind==='Quiz'){const deck=root.querySelector('[data-misc-flashcards]');if(deck){const first=require(deck,'[data-misc-card]');first.click();assert(first.textContent.includes('Hello'),'card did not turn');require(deck,'[data-card-step="-1"]').click();assert(require(deck,'output').textContent==='3 of 3'&&!deck.querySelectorAll('[data-misc-card]')[2].hidden,'deck did not wrap');return}const quiz=require(root,'[data-misc-quiz]'),questions=quiz.querySelectorAll('[data-misc-question]');assert(questions.length===2,'source quiz questions lost');send(quiz);assert(require(quiz,'output').textContent.includes('Choose'),'empty answer accepted');questions.forEach(question=>{question.querySelector('[value="1"]').checked=true;send(quiz);assert(question.querySelector('[data-result="correct"]'),'correct answer not shown');send(quiz)});assert(actions.at(-1).right===2&&actions.at(-1).total===2,'quiz score lost');return;}
 if(kind==='LicenseViewer'){const style=getComputedStyle(require(root,'pre')),luminance=value=>{const channels=value.match(/[\d.]+/g)?.slice(0,3).map(Number);assert(channels?.length===3,'license colors must resolve');return channels.map(c=>c/255).map(c=>c<=.04045?c/12.92:((c+.055)/1.055)**2.4).reduce((n,c,i)=>n+c*[.2126,.7152,.0722][i],0)},foreground=luminance(style.color),background=luminance(style.backgroundColor);assert((Math.max(foreground,background)+.05)/(Math.min(foreground,background)+.05)>=7,'license text contrast must be at least 7:1');const buttons=root.querySelectorAll('[data-misc-license]');assert(buttons.length===4&&require(root,'pre').textContent.includes('MIT'),'source license text missing');buttons[2].click();assert(require(root,'[data-license-title]').textContent==='Inter 4.1'&&require(root,'pre').textContent.includes('SIL OPEN FONT LICENSE'),'license selection not rendered');return;}
 if(kind==='Terms'){const opener=root.querySelector('[data-native-dialog-open]');if(opener){const dialog=require(root,'dialog');opener.click();require(dialog,'[data-misc-accept]').click();assert(dialog.open&&require(dialog,'[data-misc-error]').textContent,'terms accepted without agreement');require(dialog,'input').checked=true;const closed=dialogClose(dialog);require(dialog,'[data-misc-accept]').click();await closed;assert(!dialog.open&&document.activeElement===opener,'consent focus not restored');action(actions,'accept')}const cookies=root.querySelector('[data-misc-cookies]');if(cookies){require(cookies,'[data-cookies="choose"]').click();assert(!require(cookies,'[data-cookie-options]').hidden,'cookie choices did not expand');require(cookies,'input[value="Analytics"]').checked=true;require(cookies,'[data-cookies="choose"]').click();assert(actions.at(-1).values.join(',')==='Analytics','cookie choices lost')}return;}
 if(kind==='ExportDialog'){const transfer=require(root,'[data-misc-transfer]'),opener=require(transfer,'[data-native-dialog-open]'),dialog=require(transfer,'dialog'),form=require(dialog,'form');opener.click();assert(dialog.open&&dialog.matches(':modal'),'transfer must open modally');if(transfer.dataset.mode==='ExportDialog'){assert(form.querySelectorAll('[name=format]').length===4,'source radio formats missing');require(form,'[value=json]').checked=true}else{const fields=form.querySelectorAll('[data-import-field]');assert(fields.length===3,'mapping fields lost');if(transfer.dataset.mode==='CSVImporter'){assert(require(form,'[data-csv-headed]').checked&&form.querySelectorAll('tbody tr').length===3&&form.textContent.includes('Lin, Wei'),'parsed CSV rows lost')}else{const before=actions.length;send(form);assert(dialog.open&&actions.length===before&&require(form,'[data-misc-error]').textContent,'required mapping was bypassed');fields[0].querySelector('select').value='0'}fields[1].querySelector('select').value='1'}const closed=dialogClose(dialog);send(form);await closed;assert(!dialog.open&&document.activeElement===opener,'transfer did not restore opener focus');const result=actions.at(-1);if(transfer.dataset.mode==='CSVImporter')assert(result.action==='import-csv'&&result.records.length===3&&result.records[1][0]==='Lin, Wei'&&result.records[1][2]==='','CSV mapped record contract lost');else if(transfer.dataset.mode==='ImportDialog')assert(result.mapping.join(',')==='0,1,','mapping lost optional empty field');else assert(result.format==='json','export lost chosen format');return;}
 throw Error('Missing misc behavior check for '+kind);
};

const groups = {
 shell:['ColumnShell','WindowDragRegion','WindowResizeBorder','NativeMenu','Toolbar','ActivityBar','TabBar','SplashScreen','AboutDialog','TrayIcon','DockBadge','SystemNotification','MultiWindow Manager','WindowSwitcher','QuickLauncher','MiniWindow','UpdateBanner','UpdateDialog','CrashReporter','OfflineIndicator','ZoomControl'], titleBar:['TitleBar'], windowControls:['WindowControls'], statusBar:['StatusBar'],
 generation:['GenerationQueue','GenerationGrid'], variation:['VariationPicker'], mask:['InpaintCanvas'],
 media:['VideoGenerationTimeline','VideoPlayer','AudioPlayer'], audioWidgets:['AudioWaveform','AudioSpectrum','VolumeControl','PlaybackSpeedControl','MediaControls'],
 model:['ModelCard','ModelDownloadManager','ModelStatus','FineTuneJobCard'], records:['DatasetViewer','EmbeddingVisualizer'], image:['ImageViewer'], crop:['ImageCropper'], annotation:['ImageAnnotator'], device:['ScreenRecorderControls','CameraPreview','MicLevelMeter','DeviceSelector'], threeD:['3DModelViewer'],
 theme:['ThemeEditor','ThemeProvider','DensityProvider','RadiusProvider','FontProvider','HighContrastMode','ReducedMotionProvider','ThemeImporter','SyntaxThemes','Platform Style','IconThemeProvider','VibrancyBackground'], themeValues:['Surfaces','Ink','Signals','Series','Syntax','Type','Shape','Motion'], locale:['I18nProvider','LocaleNumber','RTL layout'], palette:['ColorBlindSafe Palette'], skipLink:['SkipLink'],
 clock:['Clock'], stopwatch:['Stopwatch'], calculator:['Calculator'], converter:['UnitConverter'], poll:['Poll','Quiz'], documentView:['ChangeLog Viewer','LicenseViewer','Terms','WebView','IframeEmbed'], tooling:['InspectorOverlay','FPSMeter','RenderCounter','EventLogger','DesignTokenViewer','IconBrowser','A11yChecker','ScreenshotTest Harness','ComponentGallery','PlaygroundPanel'], render:['RenderSurface']
};
const checks = {};
const add=(chapter,names,check)=>names.forEach(name=>checks[chapter+'/'+name]=async context=>{const disabled=context.root.querySelector('.ely-native-controls[disabled]'),component=context.root.dataset.elyComponent,readOnly=['shell/SplashScreen','generative/ModelStatus','generative/HardwareMonitor','media/AudioSpectrum','media/Visualizer','theme/Surfaces','theme/Ink','theme/Signals','theme/Series','theme/Syntax','theme/Type'];if(component==='generative/ImageCompare')return await comparison(context);if(disabled&&component.startsWith('shell/')&&context.root.querySelector('[data-native-shell-note]')&&!disabled.querySelector('button,input,select,textarea'))return await check(context);if(disabled&&component.startsWith('misc/')&&!disabled.querySelector('button,input,select,textarea'))return await check(context);if(disabled&&!readOnly.includes(component)){const control=require(disabled,'button,input,select,textarea');assert(control.matches(':disabled'),'disabled caller state did not disable native controls');return;}await check(context);});
add('shell',groups.shell,shell);add('shell',groups.titleBar,titleBar);add('shell',groups.windowControls,windowControls);add('shell',groups.statusBar,statusBar);add('generative',groups.generation,generation);add('generative',groups.variation,variation);add('generative',groups.mask,mask);add('generative',['ImageGenerationPanel'],generationPanel);add('generative',['TTSVoicePicker'],voicePicker);add('generative',['PromptPlayground'],promptWorkbench);add('generative',['PromptDiff'],promptHistory);add('generative',groups.media,media);add('generative',groups.model,model);add('generative',['DatasetViewer'],dataset);add('generative',['EmbeddingVisualizer'],embedding);
add('generative',['VideoGenerationTimeline'],frames);
add('generative',['AudioGenerationPlayer'],generatedAudio);
add('media',groups.media,media);add('media',groups.audioWidgets,standaloneAudio);add('media',groups.image,image);add('media',['ImageThumbnail'],thumbnails);add('media',['VideoTimeline'],timeline);add('media',['VideoThumbnailStrip'],strip);add('media',groups.crop,crop);add('media',['ImageUpload'],upload);add('media',groups.annotation,annotation);add('media',['SubtitleEditor'],subtitles);add('media',['Playlist'],playlist);add('media',groups.device,device);add('media',groups.threeD,threeD);
add('media',['AudioWaveform'],context=>{standaloneAudio(context);samples(context)});
add('theme',groups.theme,theme);add('theme',groups.themeValues,themeValues);add('i18n',groups.locale,locale);add('i18n',groups.palette,palette);add('i18n',groups.skipLink,skipLink);add('misc',['Clock','Stopwatch','Calculator','UnitConverter','QRCodeScanner','Captcha','BarcodeDisplay','Poll','Quiz','ChangeLog Viewer','LicenseViewer','Terms','WebView','IframeEmbed','ExportDialog','PrintButton','ShareSheet'],misc);
registerChecks('native',checks);
registerChecks('native',{ 'generative/ImageCompare': comparison });
